param([string]$Root=(Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path 'experiment\results\experiment-1-59'))
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest
function ReadJson($p){if(Test-Path $p){Get-Content -Raw -Encoding UTF8 $p|ConvertFrom-Json}else{$null}}
function Num($v){if($null -eq $v -or $v -eq ''){$null}else{[double]$v}}
function Summarize($dir,$condition){
 $load=ReadJson (Join-Path $dir 'load-summary.json');$adm=ReadJson (Join-Path $dir 'admission-final.json');$pool=ReadJson (Join-Path $dir 'pool-final.json');$stage=ReadJson (Join-Path $dir 'stage-final.json');$drain=ReadJson (Join-Path $dir 'mock-drain-summary.json')
 $o=$load.summary;$a=if($adm){$adm.admission}else{$null};$out=$o.outcomeCounts
 $stageMax=@{};if($stage){foreach($x in $stage.stages){if($x.stage -in @('TOKEN','AI','STORAGE')){$stageMax[$x.stage]=$x.maxInFlight}}}
 $poolFinal=@{};if($pool){foreach($x in $pool.metrics){if($x.name -match 'total.connections|pending.connections' -and $x.tags.name){$poolFinal[($x.tags.name+'.'+$x.name.Split('.')[-2])]=$x.value}}}
 [ordered]@{condition=$condition;runId=$o.experimentRunId;sourceCommit=(ReadJson (Join-Path $dir 'run-config.json')).sourceCommit;successfulRequests=$out.HTTP_200_ACCEPTED;attempts=$o.startedRequests;acceptedPerLoadSecond=if($o.durationMs){[math]::Round($out.HTTP_200_ACCEPTED/($o.durationMs/1000),2)}else{$null};successRate=if($o.startedRequests){[math]::Round(100*$out.HTTP_200_ACCEPTED/$o.startedRequests,2)}else{$null};http200P95=$o.latencyByOutcome.HTTP_200_ACCEPTED.p95;http200P99=$o.latencyByOutcome.HTTP_200_ACCEPTED.p99;http500=$out.HTTP_500_UNCONTROLLED;admission503=$out.HTTP_503_ADMISSION;timeout=$out.CLIENT_TIMEOUT;connectionError=$out.CONNECTION_ERROR;maxInFlight=$o.maxInFlight;admissionAcquired=if($a){$a.acquired}else{$null};admissionRejected=if($a){$a.rejected}else{$null};admissionReleased=if($a){$a.released}else{$null};admissionActivePeak=if($a){$a.maxObservedInUse}else{$null};admissionActiveFinal=if($a){$a.currentInUse}else{$null};permitLeak=if($a){$a.permitLeak}else{$null};drainCompleted=if($drain){$drain.drainCompleted}else{$null};drainTimeToZeroMs=if($drain){$drain.timeToZeroMs}else{$null};stageMaxInFlight=$stageMax;poolFinal=$poolFinal;poolTimeSeries='NOT_AVAILABLE';poolAvailable=if($pool){$true}else{$false};stageAvailable=if($stage){$true}else{$false};resourceAvailable=(Test-Path (Join-Path $dir 'application-resources.jsonl'))}
}
$rows=@();$map=@{G600='G600';G400='G400';G800='G800'};foreach($c in $map.Keys){$d=Join-Path $Root $c;if(Test-Path $d){$rows+=Summarize $d $c}}
$control=ReadJson (Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path 'experiment\results\experiment-1-58\C600-100-R1\load-summary.json');$co=$control.summary
$result=[ordered]@{experiment='Exp159';controlReuse=$true;controlRun='C600-100-R1';control=[ordered]@{acceptedPerLoadSecond=[math]::Round($co.outcomeCounts.HTTP_200_ACCEPTED/($co.durationMs/1000),2);successRate=if($co.startedRequests){[math]::Round(100*$co.outcomeCounts.HTTP_200_ACCEPTED/$co.startedRequests,2)}else{$null};http200P95=$co.latencyByOutcome.HTTP_200_ACCEPTED.p95;http500=$co.outcomeCounts.HTTP_500_UNCONTROLLED;timeout=$co.outcomeCounts.CLIENT_TIMEOUT;maxInFlight=$co.maxInFlight};cells=$rows;generatedAt=(Get-Date).ToUniversalTime().ToString('o')}
$outPath=Join-Path $Root 'aggregate.json';New-Item -ItemType Directory -Force -Path $Root|Out-Null;$result|ConvertTo-Json -Depth 20|Set-Content $outPath -Encoding UTF8;$result|ConvertTo-Json -Depth 20
